    """
    # Validate input: x0 and y0 must be positive integers
    if x0 <= 0 or y0 <= 0:
        return 0
    # y0 must be a multiple of x0
    if y0 % x0 != 0:
        return 0
    quotient = y0 // x0

    # Helper function for greatest common divisor
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    # Iterate over all factor pairs (a, b) such that a * b == quotient
    i = 1
    while i * i <= quotient:
        if quotient % i == 0:
            a = i
            b = quotient // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1  # (P,Q) and (Q,P) are the same
