    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalize names for case-insensitive comparison
    participant_names = {name.upper() for name in statements}
    scenario_upper = scenario.upper()

    # Preprocess day names for quick skip
    day_names_lower = {day.lower() for day in days_of_week}

    for participant, stmts in statements.items():
        participant_upper = participant.upper()
        is_liar = participant_upper in (name.upper() for name in liar_count)

        for s in stmts:
            # Skip statements about days of the week
            s_lower = s.lower()
            if any(day in s_lower.split() for day in day_names_lower):
                continue

            # Identify target of the statement
            words = s.strip().split()
            if not words:
                continue  # empty statement

            # Determine the target name (who the statement refers to)
            if words[0].lower() == "i":
                target = participant_upper
            else:
                # Remove punctuation from the first word for comparison
                first_word = words[0].strip(".,!?;:")
                target = first_word.upper()
                # If the first word is not a known participant, attempt to find it in the statement
                if target not in participant_names:
                    # Search the statement for any participant name
                    found = False
                    for pname in participant_names:
                        if pname in s_upper := s.upper():
                            target = pname
                            found = True
                            break
                    if not found:
                        # Unable to determine target, skip this statement
                        continue

            # Determine if the statement claims guilt or non-guilt
            # Look for the phrase "not guilty" or just "guilty"
            if "not guilty" in s_lower:
                guilty_claim = False
            elif "guilty" in s_lower:
                guilty_claim = True
            else:
                # Statement not about guilt, ignore
                continue

            # Evaluate the truth value of the statement
            if guilty_claim:
                truth = (scenario_upper == target)
            else:
                truth = (scenario_upper != target)

            # For liars, statements must be false; for truth tellers, statements must be true
            if is_liar:
                if truth:
                    return False  # liar said a true statement, contradiction
            else:
                if not truth:
                    return False  # truthful person said a false statement, contradiction

    return True

