    try:
        if not isinstance(T, int) or not isinstance(M, int):
            raise TypeError("T and M must be integers.")
        if T < 0 or M < 0:
            raise ValueError("T and M must be non‑negative.")
        if not isinstance(herbs, list):
            raise TypeError("herbs must be a list of (time, value) tuples.")
        if len(herbs) != M:
            # Allow mismatch but warn via exception
            raise ValueError("Length of herbs list does not match M.")
    except Exception as e:
        raise e

    # Initialize DP array where dp[t] represents the max value achievable with time t
    dp = [0] * (T + 1)

    for idx, (time_cost, value) in enumerate(herbs):
        # Skip items with negative time or value (they cannot be beneficial)
        if not isinstance(time_cost, int) or not isinstance(value, int):
            continue
        if time_cost < 0 or value < 0:
            continue
        # If the herb itself requires more time than available, it cannot be taken
        if time_cost > T:
            continue

        # Update DP array backwards to ensure each herb is used at most once
        for t in range(T, time_cost - 1, -1):
            potential = dp[t - time_cost] + value
            if potential > dp[t]:
                dp[t] = potential

    # The best value achievable with any time up to T
    return max(dp) if dp else 0

